def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    char_index = {ch: i for i, ch in enumerate(alphabet)}
    size = len(alphabet)

    transitions = [[-1] * size]
    forbidden = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                forbidden.append(False)
            state = transitions[state][c]
        forbidden[state] = True

    failure = [0] * len(transitions)
    queue = deque()

    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        forbidden[state] |= forbidden[failure[state]]

        for c in range(size):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    valid_states = [i for i in range(len(transitions)) if not forbidden[i]]
    index = {state: i for i, state in enumerate(valid_states)}
    count = len(valid_states)

    matrix = [[0] * count for _ in range(count)]
    for state in valid_states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not forbidden[target]:
                row[index[target]] += 1

    vector = [0] * count
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, coefficient in enumerate(matrix[i]):
                        if coefficient:
                            result[j] = (result[j] + value * coefficient) % mod
            vector = result

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, coefficient in enumerate(matrix[k]):
                            if coefficient:
                                squared[i][j] = (
                                    squared[i][j] + value * coefficient
                                ) % mod
            matrix = squared

    return sum(vector) % mod
